{"cards": [{"node_code": "N_0104efddd535d7c2", "definition": "研究铁路机车总装工艺、装配流程、调试方法及出厂检验标准的工程领域，涵盖从部件集成到整车性能验证的全过程。", "boundary": "本节点聚焦于机车制造后期的“装配”与“检验”环节。边界在于区分“制造工艺”（侧重零部件加工与结构制造，归入机车制造工艺）与“装配检验”（侧重系统集成、总装调试及质量验收）。若内容涉及具体零部件的加工技术，归入制造工艺；若涉及整车组装、联调联试及出厂测试，归入本节点。", "includes": ["机车总装工艺规程、装配顺序及工装夹具设计", "机车出厂前的性能试验、调试方法及质量标准", "机车装配过程中的质量控制与检验技术"], "excludes": ["机车零部件的机械加工、焊接等制造工艺（归入机车制造工艺）", "机车设计阶段的计算与图纸（归入机车设计与计算）", "机车运用阶段的检修维护（归入机务段、机车保养与检修）"], "sibling_distinctions": [{"other_code": "N_3d2b34d159c564e4", "rule": "区分依据为生产阶段：制造工艺侧重零部件及总成的加工成型；装配与检验侧重零部件的集成、总装及最终性能验证。"}, {"other_code": "N_79821ffb6f3314e8", "rule": "区分依据为工作性质：设计与计算侧重理论建模与参数确定；装配与检验侧重物理实体的组装与实测验证。"}], "cross_boundary_rule": "若内容涉及装配过程中的设计变更或工艺改进，若侧重工艺实施归本节点，若侧重设计原理归机车设计与计算。"}, {"node_code": "N_b4244f363b2db8ab", "definition": "涉及铁路机车制造企业（工厂）的组织架构、生产布局、工艺流程管理及企业运营历史的学科内容。", "boundary": "本节点聚焦于“机车制造厂”这一实体及其管理活动。边界在于区分“工厂管理”（侧重企业组织、生产计划、布局）与“具体技术”（侧重某项具体工艺或设备，归入相应技术节点）。若内容涉及特定工厂的历史沿革、产能布局或生产管理，归入本节点；若涉及通用制造技术，归入机车制造工艺或装配。", "includes": ["机车制造企业的生产组织、车间布局及物流管理", "机车制造厂的历史沿革、代表性企业及其技术特色", "机车制造企业的生产计划、成本控制及质量管理"], "excludes": ["通用的机械加工或装配技术（归入机车制造工艺或装配与检验）", "机车设计理论（归入机车设计与计算）", "机车运用与检修（归入机务段、机车保养与检修）"], "sibling_distinctions": [{"other_code": "N_3d2b34d159c564e4", "rule": "区分依据为研究对象：制造厂侧重企业层面的组织与管理；制造工艺侧重具体的技术方法与工艺规程。"}, {"other_code": "N_0104efddd535d7c2", "rule": "区分依据为层级：制造厂涉及工厂整体运营；装配与检验涉及具体的生产环节技术。"}], "cross_boundary_rule": "若内容涉及某工厂特有的装配工艺创新，若侧重工艺技术归入装配与检验，若侧重该工厂的管理模式或历史背景归入本节点。"}, {"node_code": "N_9704dbe3a5bf2486", "definition": "研究按特定用途分类的铁路机车（如调车、工矿、特种作业等）的设计特点、构造差异及运用要求的工程领域。", "boundary": "本节点聚焦于“用途”维度的机车分类。边界在于区分“动力类型”（蒸汽、内燃、电力等，归入相应动力节点）与“用途类型”（调车、工矿、救援等，归入本节点）。若内容主要描述某类动力机车的通用技术，归入动力节点；若内容强调特定用途下的特殊构造、性能指标或运用场景，归入本节点。", "includes": ["调车机车、工矿机车、救援机车等特种用途机车的设计与构造", "不同用途机车的性能参数对比及适用场景分析", "特种用途机车的专用设备及运用技术"], "excludes": ["通用干线客货机车的通用技术（归入相应动力类型节点）", "无动力车辆（归入车辆工程）", "机车通用制造工艺（归入机车制造工艺）"], "sibling_distinctions": [{"other_code": "N_b692b2cefe47f469", "rule": "区分依据为分类维度：内燃机车按动力源分类，涵盖所有内燃动力机车；各种用途机车按功能分类，可能包含内燃或电力动力的调车、工矿机车。若侧重动力原理归内燃，侧重用途特性归本节点。"}, {"other_code": "N_208cbbc9bcec10c4", "rule": "区分依据为分类维度：电力机车按动力源分类；各种用途机车按功能分类。若内容涉及电力调车机车，侧重电力传动归电力机车，侧重调车作业特性归本节点。"}], "cross_boundary_rule": "若内容涉及“内燃调车机车”，若侧重内燃机及传动系统归内燃机车，若侧重调车作业性能、构造特点及运用归本节点。"}]}
